#!/usr/bin/env python3
import json,sqlite3
c=sqlite3.connect("data/historix-master/historix_master.sqlite");r=json.load(open("data/historix-master/expansion1_report.json"))
x={"polities":c.execute("select count(*) from polities").fetchone()[0],"places":c.execute("select count(*) from places").fetchone()[0],"place_polity":c.execute("select count(*) from place_polity").fetchone()[0],"orphan_parent":c.execute("select count(*) from places p left join places q on q.place_id=p.parent_place_id where p.parent_place_id is not null and q.place_id is null").fetchone()[0],"orphan_relation":c.execute("select count(*) from place_relations r left join places a on a.place_id=r.child_place_id left join places b on b.place_id=r.parent_place_id where a.place_id is null or b.place_id is null").fetchone()[0],"missing_provenance":c.execute("select count(*) from places p left join provenance v on v.entity_type='place' and v.entity_id=p.place_id where v.provenance_id is null").fetchone()[0],"self_relation":c.execute("select count(*) from place_relations where child_place_id=parent_place_id").fetchone()[0],"lookups":r["place_time_lookups_checked"],"lookup_failures":r["place_time_lookup_failures"]}
assert x["polities"]==1583 and x["places"]>13380 and x["place_polity"]>=13380 and x["orphan_parent"]==x["orphan_relation"]==x["missing_provenance"]==x["self_relation"]==0 and x["lookups"]>=10000 and not x["lookup_failures"],x
print(json.dumps(x,indent=2))
